function h({registerIndicator:o,nulls:c}){o({id:"oa-hl2",name:"Midprice (HL2)",category:"Numerics",placement:"onchart",inputs:[],plots:[{key:"hl2",type:"line",title:"HL2",style:{color:"#ffeb3b",lineWidth:2}}],calc(t){const i=new Array(t.length).fill(NaN);for(let e=0;e<t.length;e++){const l=t[e].high,n=t[e].low;!Number.isFinite(l)||!Number.isFinite(n)||(i[e]=(l+n)*.5)}return{hl2:c(i)}}})}export{h as default};
